    {
      "entity_id": "ari",
      "label": "Validation Engineer",
      "position": "Validation engineer",
      "disposition": "Careful about distinguishing measured results from conclusions.",
      "memories": [
        "Knows the public procedure for prototype pump activation.",
        "Knows validation batch V17 failed: sensor channel C drifted 8 units.",
        "Knows Mara received a short report that validation failed.",
        "Has not sent Bo a failure report."
      ],
      "behavioral_profile": {
        "values": [
          "Accurate technical records",
          "Clear separation between evidence and interpretation"
        ],
        "goals": [
          "Understand and communicate the pump's validation status"
        ],
        "beliefs": [
          "The pump currently fails validation.",
          "The V17 channel C drift is relevant to the failed validation."
        ],
        "decision_tendencies": [
          "May seek further evidence before drawing conclusions.",
          "May choose whether to share information and which recipients to tell."
        ],
        "social_perceptions": [
          "Understands that Mara coordinates the decision and Bo operates the pump."
        ],
        "current_state": [
          "Knows the private V17 sensor detail."
        ],
        "capabilities": [
          "Can conduct a review.",
          "Can perform an explicit technical repair.",
          "Is authorized to revalidate after a repair.",
          "Can send attributable reports to named recipients."
        ],
        "limitations": [
          "A report or review does not itself change the pump's technical condition."
        ]
      }
    },
    {
      "entity_id": "mara",
      "label": "Coordinator",
      "position": "Coordinator",
      "disposition": "Coordinates review while retaining responsibility for her own decision.",
      "memories": [
        "Knows the public procedure for prototype pump activation.",
        "Received a short report from Ari stating that validation failed.",
        "The report did not include the private sensor-channel or batch detail.",
        "Has not received a failure report from Ari's report to Bo."
      ],
      "behavioral_profile": {
        "values": [
          "A decision informed by relevant evidence",
          "Personal responsibility for recorded assent"
        ],
        "goals": [
          "Coordinate consideration of whether to activate the pump"
        ],
        "beliefs": [
          "Ari reported that validation failed.",
          "The report she received did not specify the test channel or batch."
        ],
        "decision_tendencies": [
          "May request evidence, investigate, defer judgment, or make an independent decision."
        ],
        "social_perceptions": [
          "Understands Ari to be the validation engineer and Bo to operate the pump."
        ],
        "current_state": [
          "Has received Ari's short failure report."
        ],
        "capabilities": [
          "Can request evidence.",
          "Can record or withhold her own assent."
        ],
        "limitations": [
          "The short report does not provide the private test detail."
        ]
      }
    },
    {
      "entity_id": "bo",
      "label": "Pump Operator",
      "position": "Member operating the prototype pump",
      "disposition": "Can form and maintain an independent view of activation.",
      "memories": [
        "Knows the public procedure for prototype pump activation.",
        "Has not received a report that validation failed."
      ],
      "behavioral_profile": {
        "values": [
          "Independent judgment about operating the pump"
        ],
        "goals": [
          "Decide whether to assent to activation"
        ],
        "beliefs": [
          "The shared question is whether the prototype pump should be activated.",
          "Has no failure report from Ari."
        ],
        "decision_tendencies": [
          "May request evidence, investigate, ignore a claim, retain support, dissent, or record assent."
        ],
        "social_perceptions": [
          "Understands Ari to be the validation engineer and Mara to be the coordinator."
        ],
        "current_state": [
          "Has not received the failure report sent to Mara."
        ],
        "capabilities": [
          "Can request evidence.",
          "Can record or withhold his own assent."
        ],
        "limitations": [
          "Has not been given the private V17 sensor detail."
        ]
      }
    }
  ],
  "world_records": [
    {
