      "desired_effects": [
        "The filing can make the failed-validation status public.",
        "The filing does not disclose the V17 channel detail.",
        "The filing does not change the pump's technical condition."
      ],
      "fidelity_need": "bounded",
      "causally_material": true
    },
    {
      "request_id": "explicit_technical_repair",
      "subject_refs": [
        "ari",
        "prototype_pump"
      ],
      "behavior_description": "Ari may choose to perform an explicit technical repair.",
      "desired_effects": [
        "A repair is a technical intervention, not an effect of waiting, reporting, or completing a review.",
        "Only a repair that actually corrects the relevant condition can enable passing revalidation."
