      "desired_effects": [
        "Passing revalidation clears the technical activation hold only.",
        "A report of passing or failing does not itself change the technical condition.",
        "Passing validation does not force either required actor to assent."
      ],
      "fidelity_need": "bounded",
      "causally_material": true
    },
    {
      "request_id": "independent_activation_assent",
      "subject_refs": [
        "mara",
        "bo",
        "prototype_pump"
      ],
      "behavior_description": "Mara and Bo may independently decide whether to record their own assent to activation.",
      "desired_effects": [
        "Activation requires passing validation and each required actor's own recorded assent.",
        "A request, report, review, or another person's assent does not force an actor's support or recorded assent.",
        "Either actor may dissent, withhold assent, or retain a view despite new information."
      ],
      "fidelity_need": "exact",
      "causally_material": true
    }
  ],
